#!/usr/bin/env node
/**
 * The developer portal publishes every /api/v1 route svc-trade serves. Who may call each route, and the scopes a key
 * needs, are declared once, where svc-trade registers it; this command writes them into the customer app, which cannot
 * import svc-trade: apps/customer/src/features/developers/served-routes.generated.ts. The portal's REST_REFERENCE takes
 * each route's access and scopes from that file and adds only its words (name, product, summary).
 *
 *   node tooling/ci/published-routes.mjs           check: fails only when the generated file is stale
 *   node tooling/ci/published-routes.mjs --write   rewrite it from svc-trade's registrations
 *
 * It also names a served route ROUTE_WORDS gives no words, and words for a route no longer served: a route's name,
 * product and summary are prose the change writes, so the push is told before the customer tests are.
 *
 * The check runs from .githooks/pre-push (gates.mjs --before-push) and in CI. Before it, the same list was kept by
 * hand three times: in the registrations, in svc-trade's published-routes.txt and in REST_REFERENCE's rows, and a
 * correct route change lost its push until the second and third were edited (#8079, #8102, #8142, #8146, #8480,
 * #8518, #8571).
 *
 * The parser is svc-trade's own (route-declarations.test-harness.ts), which developers-reference.test.ts also runs.
 */
import { readFileSync, readdirSync, existsSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { pathToFileURL } from 'node:url';

const ROOT = process.cwd();
const SRC = join(ROOT, 'services/svc-trade/src');
const HARNESS = join(SRC, 'route-declarations.test-harness.ts');
export const GENERATED_PATH = 'apps/customer/src/features/developers/served-routes.generated.ts';
const GENERATED = join(ROOT, GENERATED_PATH);
const REFERENCE_PATH = 'apps/customer/src/features/developers/developers-reference.ts';
const REFERENCE = join(ROOT, REFERENCE_PATH);
const COMMAND = 'node tooling/ci/published-routes.mjs --write';

/** The generated file's text for these lines (each `declarationKey`: method, path, access, scopes joined by +). */
export function generatedText(lines) {
  return [
    '/**',
    ' * Every /api/v1 route svc-trade registers, one per line: method, path, who may call it and the scopes a key needs,',
    ` * as each registration declares. Generated by \`${COMMAND}\`: never edit it by hand.`,
    ' */',
    'export const SERVED_ROUTES: readonly string[] = [',
    ...lines.map((line) => `  '${line}',`),
    '];',
    '',
  ].join('\n');
}

/** The lines the generated text holds (the inverse of generatedText); null when it is not that file's shape. */
export function generatedLines(text) {
  const body = /export const SERVED_ROUTES: readonly string\[\] = \[\n([\s\S]*?)\];\n/.exec(text);
  if (!body) return null;
  return [...body[1].matchAll(/^ {2}'([^']*)',$/gm)].map((m) => m[1]);
}

/** The served route lines, sorted, from svc-trade's sources; refuses a parse that lost routes or a route declared two ways. */
export async function servedRoutes() {
  if (!existsSync(HARNESS)) throw new Error(`${HARNESS.slice(ROOT.length + 1)} is missing`);
  const { declarationKey, isRouteSource, tradeDeclarations } = await import(pathToFileURL(HARNESS).href);
  const files = readdirSync(SRC, { recursive: true })
    .filter((file) => file.endsWith('.ts') && isRouteSource(file))
    .map((file) => ({ file, text: readFileSync(join(SRC, file), 'utf8') }));
  const declared = tradeDeclarations(files);
  if (declared.length < 100) throw new Error(`read ${declared.length} svc-trade routes, fewer than 100: the parser lost them`);
  const lines = [...new Set(declared.map(declarationKey))].sort();
  const seen = new Map();
  for (const line of lines) {
    const route = line.split(' ').slice(0, 2).join(' ');
    if (seen.has(route)) throw new Error(`${route} is registered twice with different access or scopes: ${seen.get(route)} | ${line}`);
    seen.set(route, line);
  }
  return lines;
}

/**
 * The routes in `lines` that ROUTE_WORDS in `reference` (developers-reference.ts's text) gives no words, and the worded
 * routes not in `lines`. A route's words (its name, product and summary) are prose no command can write, so this says
 * which before the push instead of the customer tests after it.
 */
export function wordsProblems(lines, reference) {
  const start = reference.indexOf('export const ROUTE_WORDS');
  if (start < 0) return ['ROUTE_WORDS is missing from ' + REFERENCE_PATH];
  const block = reference.slice(start, reference.indexOf('\n];\n', start));
  const worded = new Set([...block.matchAll(/method: '(\w+)',\s*path: '([^']+)'/g)].map((m) => `${m[1]} ${m[2]}`));
  const served = new Set(lines.map((line) => line.split(' ').slice(0, 2).join(' ')));
  return [
    ...[...served].filter((route) => !worded.has(route)).map((route) => `served with no words: ${route}`),
    ...[...worded].filter((route) => !served.has(route)).map((route) => `worded, not served: ${route}`),
  ];
}

async function main() {
  const write = process.argv.includes('--write');
  let lines;
  try {
    lines = await servedRoutes();
  } catch (error) {
    console.error(`✖ PUBLISHED ROUTES FAILED — ${error.message}`);
    process.exit(1);
  }
  const text = generatedText(lines);
  if (write) {
    writeFileSync(GENERATED, text);
    console.log(`✓ published routes: wrote the ${lines.length} routes svc-trade registers to ${GENERATED_PATH}`);
  }
  const current = existsSync(GENERATED) ? readFileSync(GENERATED, 'utf8') : '';
  const words = wordsProblems(lines, existsSync(REFERENCE) ? readFileSync(REFERENCE, 'utf8') : '');
  if (current === text && !words.length) {
    console.log(`✓ published routes: ${GENERATED_PATH} is the ${lines.length} routes svc-trade registers, each worded`);
    return;
  }
  const show = (diff) => {
    for (const line of diff.slice(0, 20)) console.error(`  ${line}`);
    if (diff.length > 20) console.error(`  and ${diff.length - 20} more`);
  };
  if (current !== text) {
    const have = new Set(generatedLines(current) ?? []);
    const want = new Set(lines);
    console.error(`✖ PUBLISHED ROUTES FAILED — ${GENERATED_PATH} is stale: run \`${COMMAND}\` and commit it`);
    show([
      ...lines.filter((line) => !have.has(line)).map((line) => `registered, not in the file: ${line}`),
      ...[...have].filter((line) => !want.has(line)).map((line) => `in the file, not registered: ${line}`),
    ]);
  }
  if (words.length) {
    console.error(
      `✖ PUBLISHED ROUTES FAILED — ROUTE_WORDS in ${REFERENCE_PATH} must word each served route once: ` +
        'give a new route its name, product and summary there, and remove the row of a route no longer served',
    );
    show(words);
  }
  process.exit(1);
}

if (import.meta.url === pathToFileURL(process.argv[1] ?? '').href) await main();
